        {
            "heading": "scope--exclusions",
            "content": "**Embeddings are never compressed.** `open-sse/handlers/embeddings.ts` never calls any\r\ncompression engine — the request/response bodies pass straight to the executor untouched.\r\nThis is structural today (embeddings and chat completions are disjoint handlers), not a\r\nruntime check, but it means the vector-distortion concern in #8034 has no exposure surface\r\nin the embeddings path."
        },
        {
            "heading": "scope--exclusions",
            "content": "**Per-model/endpoint exclusion filter (#8034).** For chat completions, an operator can name\r\nmodel ids / `provider/model` targets that must never be compressed — a guardrail useful if\r\ncompression is ever wired closer to an embeddings-adjacent path later, and generally useful\r\nfor any model whose exact byte-for-byte prompt matters (deterministic evals, cache-sensitive\r\nprefixes, etc.)."
        },
        {
            "heading": "scope--exclusions",
            "content": "Settings field: `exclusions?: string[]` on the global compression config\r\n(`GET`/`PUT /api/settings/compression`), persisted via the existing `key_value` compression\r\nnamespace (`src/lib/db/compression.ts`) — no new table."
        },
        {
            "heading": "scope--exclusions",
            "content": "Dashboard tab: **Dashboard → Compression → Exclusions**\r\n(`/dashboard/compression/exclusions`)."
        },
        {
            "heading": "scope--exclusions",
            "content": "Pattern syntax: `*` is the only wildcard. Every other regex metacharacter in a pattern is\r\nescaped before matching, so `gpt-5.6` matches the literal string only, never `gpt-5x6`\r\n(ReDoS-safe, bounded, no nested quantifiers). Patterns match case-insensitively against\r\nboth the bare model id and the `provider/model` composite — `gpt-5-6`, `openai/gpt-5-6`,\r\nand `openai/*` all work, and `*` alone excludes every model."
        },
        {
            "heading": "scope--exclusions",
            "content": "Matching: `isCompressionExcluded()` / `normalizeCompressionExclusions()` in\r\n`open-sse/services/compression/exclusions.ts`. `chatCore.ts` checks the excluded target\r\nright after resolving compression settings, **before any engine runs**, and treats a match\r\nexactly like compression being globally disabled — the request body is provably\r\nbyte-identical. The skip is recorded via `writeCompressionSkip(..., \"excluded\")` for\r\nanalytics visibility."
        },
        {
            "heading": "scope--exclusions",
            "content": "Default (empty/absent list): identical to pre-#8034 behavior — nothing is excluded."
        },
        {
            "heading": "known-limitations",
            "content": "**LLMLingua-2 (SLM) requires co-located optional deps.** The worker only runs in a\r\nproduction build when `@atjsh/llmlingua-2` + peers are co-located into\r\n`dist/node_modules` (see `scripts/build/colocateOptionals.mjs`, #4286). Without them the\r\nengine fail-opens (returns the original text). Worker resolution no longer depends on\r\n`import.meta.url` (it dies in the standalone bundle) — it anchors on the runtime\r\ncwd / `argv[1]`."
        },
        {
            "heading": "known-limitations",
            "content": "**Caveman language packs `de` / `fr` / `ja` are partial.** They ship `context` +\r\n`filler` + `structural` rules but no `dedup` / `ultra` packs, so `ultra` intensity is\r\nno stronger than `full` for those languages (they use only their own rules — there is no\r\nsilent fall-back to the English `dedup`/`ultra` rules, which would mangle foreign text).\r\n`en` / `es` / `id` / `pt-BR` are complete. Contributions of `dedup.json` + `ultra.json`\r\nfor the partial packs are welcome."
        },
        {
            "heading": "known-limitations",
            "content": "**Stacked telemetry only lists engines that compressed.** A stacked-pipeline step whose\r\nengine ran but produced 0 % savings returns `stats:null` and so does not appear in\r\n`engineBreakdown` — indistinguishable from a step that was skipped. Distinguishing\r\n\"ran, 0 %\" from \"skipped\" would require a breakdown-model change and is deferred."
        },
        {
            "heading": "validation",
            "content": "The focused gates for this area are:"
        }
